#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, cnt = 0, i = 0, n = 0;
    // 先读天数和记录；0 天时后面的循环自然不执行。
    n = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    ans = 0;
    cnt = 0;
    for (i = 0; i < n; i += 1) {
        // cnt 只描述以当前日期结尾的连续段；0 会切断这一段。
        if (a[i] == 1) {
            cnt = (cnt + 1);
        }
        else {
            cnt = 0;
        }
        // 保存历史最大长度，不能在断段时清零 ans。
        ans = mx(ans, cnt);
    }
    // 最长段不一定在末尾，所以输出 ans 而不是 cnt。
    emit(ans);
    return 0;
}

